:root {
  /* ── Primary palette (brand kit) ────────── */
  --fire-red: #FF2D2D;
  --fire-red-press: #E11919;
  --energy-coral: #FF6A4D;
  --magenta: #D81B7A;
  --ink-black: #0A0A0A;
  --slate: #22252B;
  --soft-gray: #F2F3F5;

  /* Secondary */
  --sunset-orange: #FFBA00;
  --neon-pink: #FF007A;
  --purple-power: #8B00FF;
  --electric-blue: #246BFF;
  --teal-boost: #00C2A8;
  --lime-pop: #A7F30A;

  /* Neutrals */
  --gray-50:  #FAFAFB;
  --gray-100: #F0F1F3;
  --gray-200: #E4E6EA;
  --gray-400: #9AA1AC;
  --gray-700: #4B5158;

  /* App (dark product surface) */
  --bg: #0A0A0A;
  --bg-2: #121215;
  --surface: #18181D;
  --surface-2: #1E1E24;
  --surface-3: #2A2A33;
  --line: rgba(255,255,255,0.08);
  --line-2: rgba(255,255,255,0.14);

  --text: #FFFFFF;
  --text-dim: rgba(255,255,255,0.68);
  --text-faint: rgba(255,255,255,0.42);
  --text-mute: rgba(255,255,255,0.22);

  /* Semantic */
  --brand: var(--fire-red);
  --brand-press: var(--fire-red-press);
  --accent: var(--energy-coral);
  --live: var(--fire-red);
  --win: var(--teal-boost);
  --gold: var(--sunset-orange);
  --info: var(--electric-blue);
  --warn: var(--sunset-orange);
  --danger: var(--fire-red);

  /* Gradients (from brand kit) */
  --grad-blaze: linear-gradient(135deg, #FF2D2D 0%, #D81B7A 100%);
  --grad-energy: linear-gradient(135deg, #FF6A4D 0%, #FF007A 100%);
  --grad-magenta: linear-gradient(135deg, #D81B7A 0%, #8B00FF 100%);
  --grad-sunset: linear-gradient(135deg, #FFBA00 0%, #FF2D2D 100%);
  --grad-neon: linear-gradient(135deg, #FF007A 0%, #FFBA00 100%);
  --grad-ocean: linear-gradient(135deg, #246BFF 0%, #00C2A8 100%);

  /* Type stacks */
  --font-display: "Sora", -apple-system, "Helvetica Neue", sans-serif;
  --font-ui: "Inter", -apple-system, "Helvetica Neue", sans-serif;
  --font-mono: "Space Mono", "SF Mono", "JetBrains Mono", monospace;

  /* Radii */
  --r-xs: 4px; --r-sm: 8px; --r-md: 12px; --r-lg: 16px; --r-xl: 20px; --r-2xl: 24px;
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0;
  background: #050505;
  color: var(--text);
  font-family: var(--font-ui);
  font-feature-settings: "ss01", "cv01";
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  letter-spacing: -0.005em;
}
body {
  display: flex; align-items: center; justify-content: center;
  padding: 32px 24px;
  background:
    radial-gradient(1100px 600px at 20% 0%, rgba(255,45,45,0.07), transparent 60%),
    radial-gradient(900px 500px at 90% 100%, rgba(216,27,122,0.05), transparent 60%),
    #050505;
}
button { font-family: var(--font-ui); cursor: pointer; }

/* App screen container */
.fm-screen {
  width: 100%;
  min-height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--text);
  -webkit-overflow-scrolling: touch;
}
.fm-screen { scrollbar-width: none; }
.fm-screen::-webkit-scrollbar { display: none; }

/* ── Brand mark ───────────────────────────── */
.brand-mark {
  display: inline-flex; align-items: baseline; gap: 0.45em;
  line-height: 1;
  font-family: var(--font-display);
}
.brand-mark .fm-glyph {
  align-self: center;
  width: 1.55em; height: 1.55em;
  background-image: url("data:image/png;base64,");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  flex-shrink: 0;
  filter: drop-shadow(0 4px 10px rgba(255,45,45,0.35));
}
.brand-mark .fm-word { font-family: var(--font-display); display: inline-flex; align-items: baseline; }
.brand-mark .fm-fans { font-style: italic; font-weight: 800; color: var(--fire-red); letter-spacing: -0.04em; }
.brand-mark .fm-dot { color: var(--fire-red); font-weight: 800; font-style: italic; }
.brand-mark .fm-market { font-weight: 800; color: var(--text); letter-spacing: -0.04em; }
.brand-mark.on-light .fm-market { color: var(--ink-black); }

/* ── Type scale ───────────────────────────── */
.t-display { font-family: var(--font-display); font-weight: 800; letter-spacing: -0.03em; line-height: 1.0; }
.t-display-it { font-style: italic; }
.t-h1 { font-family: var(--font-display); font-weight: 800; font-size: 28px; line-height: 1.05; letter-spacing: -0.025em; }
.t-h2 { font-family: var(--font-display); font-weight: 700; font-size: 22px; line-height: 1.15; letter-spacing: -0.02em; }
.t-h3 { font-family: var(--font-display); font-weight: 600; font-size: 17px; line-height: 1.2; letter-spacing: -0.01em; }
.t-body { font-family: var(--font-ui); font-weight: 400; font-size: 14px; line-height: 1.5; }
.t-caption { font-family: var(--font-ui); font-weight: 500; font-size: 12px; line-height: 1.4; color: var(--text-faint); }
.t-label { font-family: var(--font-ui); font-weight: 700; font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-faint); }
.t-data { font-family: var(--font-mono); font-variant-numeric: tabular-nums; font-weight: 700; }

/* ── Buttons ──────────────────────────────── */
.btn {
  appearance: none; border: 0; outline: 0;
  font-family: var(--font-ui); font-weight: 700;
  border-radius: var(--r-md);
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  transition: transform 0.08s ease, background 0.15s ease, box-shadow 0.15s ease;
  text-transform: uppercase; letter-spacing: 0.06em;
}
.btn:active { transform: scale(0.98); }
.btn-primary { background: var(--fire-red); color: #fff; padding: 14px 22px; font-size: 13px; font-weight: 800; box-shadow: 0 6px 20px rgba(255,45,45,0.32); }
.btn-primary:hover { background: var(--fire-red-press); }
.btn-secondary { background: rgba(255,255,255,0.06); color: var(--text); padding: 14px 22px; font-size: 13px; border: 1px solid rgba(255,255,255,0.14); }
.btn-tertiary { background: transparent; color: var(--fire-red); padding: 10px 14px; font-size: 13px; font-weight: 800; }
.btn-ghost { background: transparent; color: var(--text); border: 1px solid var(--line-2); padding: 12px 18px; font-size: 13px; }
.btn-cta-full { width: 100%; padding: 16px; font-size: 14px; border-radius: var(--r-md); }
.btn-loading { position: relative; color: transparent !important; }
.btn-loading::after {
  content: ""; position: absolute; inset: 0; margin: auto;
  width: 18px; height: 18px;
  border: 2px solid rgba(255,255,255,0.3);
  border-top-color: #fff; border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ── Tags / chips ────────────────────────── */
.tag {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 10px; font-weight: 700; font-family: var(--font-ui);
  padding: 4px 8px; border-radius: var(--r-xs);
  text-transform: uppercase; letter-spacing: 0.1em;
}
.tag-live { background: var(--fire-red); color: #fff; }
.tag-live .dot { width: 6px; height: 6px; border-radius: 50%; background: #fff; animation: pulse 1.4s ease-in-out infinite; }
.tag-soft { background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.85); border: 0.5px solid rgba(255,255,255,0.08); }
.tag-hot { background: var(--magenta); color: #fff; }
.tag-trending { background: var(--energy-coral); color: #fff; }
.tag-win { background: rgba(0,194,168,0.18); color: var(--teal-boost); }
.tag-gold { background: rgba(255,186,0,0.18); color: var(--sunset-orange); }
.tag-pro { background: rgba(255,45,45,0.16); color: var(--fire-red); }
.tag-elite { background: rgba(216,27,122,0.16); color: var(--magenta); }

@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.55; transform: scale(0.85); } }

/* ── Stat chips ─────────────────────────── */
.stat-chip {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-md);
  padding: 12px 14px; display: flex; flex-direction: column; gap: 2px; min-width: 0;
}
.stat-chip .v { font-family: var(--font-mono); font-weight: 700; font-size: 22px; color: var(--text); letter-spacing: -0.02em; display: flex; align-items: center; gap: 6px; }
.stat-chip .v.red { color: var(--fire-red); }
.stat-chip .v.win { color: var(--teal-boost); }
.stat-chip .k { font-family: var(--font-ui); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.12em; color: var(--text-faint); }

/* ── Cards ────────────────────────────────── */
.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-lg); padding: 16px; }
.card-elev { background: var(--surface-2); border-radius: var(--r-lg); padding: 16px; }

/* Pick card — team vs team */
.pick-card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-lg);
  padding: 14px; display: grid; grid-template-columns: 1fr 96px; gap: 14px;
}
.pick-card .team-row { display: flex; align-items: center; gap: 10px; padding: 6px 0; }
.pick-card .team-row + .team-row { border-top: 0.5px solid var(--line); }
.pick-card .team-logo {
  width: 28px; height: 28px; border-radius: 50%; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-display); font-weight: 800; font-size: 11px;
}
.pick-card .team-name { flex: 1; font-weight: 700; font-size: 14px; letter-spacing: -0.01em; }
.pick-card .team-line { font-family: var(--font-mono); font-weight: 700; font-size: 13px; color: var(--text-dim); }
.pick-card .conf-box {
  background: rgba(0,194,168,0.12); border: 1px solid rgba(0,194,168,0.25);
  border-radius: var(--r-md); padding: 10px 8px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
}
.pick-card .conf-v { font-family: var(--font-mono); font-weight: 700; font-size: 18px; color: var(--teal-boost); }
.pick-card .conf-k { font-size: 9px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--teal-boost); margin-top: 2px; }
.pick-card .conf-v.units { color: var(--fire-red); }
.pick-card .conf-k.units { color: var(--fire-red); }
.pick-card .meta-row {
  grid-column: 1 / -1; display: flex; justify-content: space-between; align-items: center;
  padding-top: 10px; border-top: 0.5px solid var(--line);
  font-size: 11px; color: var(--text-faint); font-weight: 500;
}

/* ── Alert banners ─────────────────────────── */
.alert { display: flex; gap: 12px; align-items: flex-start; padding: 12px 14px; border-radius: var(--r-md); font-size: 13px; }
.alert .a-ic { width: 22px; height: 22px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.alert-success { background: rgba(0,194,168,0.10); border: 1px solid rgba(0,194,168,0.25); color: #d6fff5; }
.alert-success .a-ic { background: var(--teal-boost); color: #fff; }
.alert-warn    { background: rgba(255,186,0,0.10); border: 1px solid rgba(255,186,0,0.25); color: #fff3d4; }
.alert-warn .a-ic { background: var(--sunset-orange); color: #000; }
.alert-info    { background: rgba(36,107,255,0.10); border: 1px solid rgba(36,107,255,0.25); color: #d4e3ff; }
.alert-info .a-ic { background: var(--electric-blue); color: #fff; }
.alert-error   { background: rgba(255,45,45,0.10); border: 1px solid rgba(255,45,45,0.25); color: #ffd6d6; }
.alert-error .a-ic { background: var(--fire-red); color: #fff; }
.alert .a-title { font-weight: 700; font-size: 13px; color: #fff; }
.alert .a-sub   { font-size: 12px; color: var(--text-faint); margin-top: 2px; }

/* ── Rails ────────────────────────────────── */
.row-rail {
  display: flex; gap: 12px; overflow-x: auto; overflow-y: hidden;
  padding: 4px 16px 18px; scroll-snap-type: x mandatory;
}
.row-rail::-webkit-scrollbar { display: none; }
.row-rail { scrollbar-width: none; }
.row-rail > * { scroll-snap-align: start; flex-shrink: 0; }
.rail-title { display: flex; align-items: center; justify-content: space-between; padding: 22px 16px 12px; }
.rail-title h3 { margin: 0; font-family: var(--font-display); font-size: 17px; font-weight: 700; letter-spacing: -0.01em; }
.rail-title .more { font-size: 11px; color: var(--text-faint); font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; display: inline-flex; align-items: center; gap: 4px; }

/* ── Tab bar ──────────────────────────────── */
.tabbar {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: grid; grid-template-columns: repeat(5, 1fr);
  padding: 8px 4px 28px;
  background: linear-gradient(180deg, rgba(10,10,10,0) 0%, rgba(10,10,10,0.92) 30%, rgba(10,10,10,1) 100%);
  backdrop-filter: blur(20px);
  border-top: 0.5px solid rgba(255,255,255,0.06);
  z-index: 30;
}
.tabbar-item { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 8px 4px; color: var(--text-faint); font-size: 10px; font-weight: 600; letter-spacing: 0.04em; border: 0; background: transparent; }
.tabbar-item.active { color: var(--text); }
.tabbar-item.active.center { color: var(--fire-red); }

/* ── Tabs (underlined) ──────────────────── */
.tabs { display: flex; gap: 22px; padding: 0 16px; border-bottom: 1px solid var(--line); overflow-x: auto; scrollbar-width: none; }
.tabs::-webkit-scrollbar { display: none; }
.tab { background: transparent; border: 0; color: var(--text-faint); padding: 12px 0; font-family: var(--font-ui); font-weight: 600; font-size: 14px; position: relative; flex-shrink: 0; cursor: pointer; }
.tab.active { color: var(--text); font-weight: 700; }
.tab.active::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; background: var(--fire-red); border-radius: 2px; }

/* ── Segmented control ──────────────────── */
.seg { display: inline-flex; padding: 4px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-md); }
.seg-item { background: transparent; border: 0; padding: 8px 18px; color: var(--text-faint); font-weight: 600; font-size: 13px; border-radius: var(--r-sm); }
.seg-item.active { background: var(--fire-red); color: #fff; }

/* ── Filter chips ───────────────────────── */
.chip { display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px; background: var(--surface); border: 1px solid var(--line); font-size: 13px; font-weight: 600; color: var(--text); flex-shrink: 0; }
.chip.active { background: rgba(255,45,45,0.12); border-color: var(--fire-red); color: var(--fire-red); }

/* ── Toggle ───────────────────────────────── */
.toggle { width: 44px; height: 26px; border-radius: 999px; background: var(--surface-3); position: relative; cursor: pointer; transition: background 0.18s; flex-shrink: 0; }
.toggle::after { content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; transition: left 0.18s; }
.toggle.on { background: var(--fire-red); }
.toggle.on::after { left: 21px; }

/* ── Progress bars ───────────────────────── */
.prob-bar { height: 8px; border-radius: 999px; background: rgba(255,255,255,0.08); overflow: hidden; position: relative; }
.prob-fill { position: absolute; left: 0; top: 0; bottom: 0; background: var(--grad-blaze); border-radius: 999px; transition: width 0.4s ease; }
.prob-fill.win { background: linear-gradient(90deg, var(--teal-boost), var(--lime-pop)); }
.prob-fill.gold { background: linear-gradient(90deg, var(--sunset-orange), var(--fire-red)); }

/* ── Avatar ───────────────────────────────── */
.avatar { border-radius: 50%; background: linear-gradient(135deg, var(--a1, #FF2D2D), var(--a2, #D81B7A)); display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 800; font-family: var(--font-display); flex-shrink: 0; }
.avatar.square { border-radius: 18px; }

/* ── Top nav ──────────────────────────────── */
.topnav { position: sticky; top: 0; z-index: 25; padding: 50px 16px 12px; background: linear-gradient(180deg, rgba(10,10,10,0.96) 0%, rgba(10,10,10,0.65) 70%, rgba(10,10,10,0) 100%); backdrop-filter: blur(14px); }
.topnav-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.topnav-cats { display: flex; gap: 8px; margin-top: 14px; overflow-x: auto; scrollbar-width: none; }
.topnav-cats::-webkit-scrollbar { display: none; }
.icon-btn { width: 38px; height: 38px; border-radius: 999px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.06); display: flex; align-items: center; justify-content: center; color: #fff; }

/* ── Placeholder image ───────────────────── */
.ph { position: relative; background: linear-gradient(135deg, var(--ph-1, #2a2a40) 0%, var(--ph-2, #14141f) 100%); overflow: hidden; }
.ph::before { content: ""; position: absolute; inset: 0; background: radial-gradient(80% 60% at 30% 30%, rgba(255,255,255,0.08), transparent 60%), radial-gradient(60% 40% at 80% 90%, rgba(0,0,0,0.4), transparent 60%); pointer-events: none; }
.ph-grain::after { content: ""; position: absolute; inset: 0; background-image: radial-gradient(1px 1px at 10% 20%, rgba(255,255,255,0.08), transparent), radial-gradient(1px 1px at 70% 80%, rgba(255,255,255,0.06), transparent), radial-gradient(1px 1px at 40% 60%, rgba(255,255,255,0.05), transparent); background-size: 200px 200px; pointer-events: none; mix-blend-mode: overlay; }

/* ── Sheet ───────────────────────────────── */
.sheet-backdrop { position: absolute; inset: 0; background: rgba(0,0,0,0.7); backdrop-filter: blur(8px); z-index: 40; display: flex; align-items: flex-end; }
.sheet { background: var(--surface); width: 100%; border-radius: 24px 24px 0 0; padding: 12px 20px 36px; position: relative; max-height: 92%; overflow-y: auto; }
.sheet::-webkit-scrollbar { display: none; }
.sheet-handle { width: 38px; height: 4px; border-radius: 999px; background: rgba(255,255,255,0.25); margin: 6px auto 18px; }

/* ── Compliance ──────────────────────────── */
.comp-row { display: flex; align-items: flex-start; gap: 12px; padding: 14px 0; border-bottom: 0.5px solid var(--line); }
.comp-row:last-child { border-bottom: 0; }
.comp-check { width: 28px; height: 28px; border-radius: 50%; background: rgba(0,194,168,0.15); color: var(--teal-boost); display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 14px; font-weight: 800; }
.comp-check.pending { background: rgba(255,255,255,0.08); color: var(--text-faint); }
.comp-check.running { background: rgba(36,107,255,0.15); color: var(--electric-blue); }

/* ── Confetti ────────────────────────────── */
.confetti { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.confetti i { position: absolute; top: -10px; width: 6px; height: 10px; animation: fall linear infinite; }
@keyframes fall { 0% { transform: translateY(-20px) rotate(0); opacity: 1; } 100% { transform: translateY(800px) rotate(720deg); opacity: 0; } }

/* ── Banner ─────────────────────────────── */
.banner { margin: 0 16px 12px; padding: 10px 12px; border-radius: var(--r-md); font-size: 12px; display: flex; align-items: center; gap: 8px; font-weight: 600; }
.banner-browse { background: rgba(36,107,255,0.12); color: #d4e3ff; border: 1px solid rgba(36,107,255,0.3); }
.banner-blocked { background: rgba(255,45,45,0.12); color: #ffd6d6; border: 1px solid rgba(255,45,45,0.3); }

/* ── Shimmer ─────────────────────────────── */
.shimmer { background: linear-gradient(90deg, rgba(255,255,255,0.04), rgba(255,255,255,0.1), rgba(255,255,255,0.04)); background-size: 200% 100%; animation: shimmer 1.4s linear infinite; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* ── Live ticker ─────────────────────────── */
.ticker { display: flex; gap: 22px; white-space: nowrap; animation: ticker 30s linear infinite; }
@keyframes ticker { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
.ticker-wrap { overflow: hidden; border-top: 0.5px solid var(--line); border-bottom: 0.5px solid var(--line); padding: 9px 0; background: var(--bg-2); }

/* ── Mascot ─────────────────────────────── */
.mascot { background-image: url("data:image/png;base64,"); background-size: contain; background-repeat: no-repeat; background-position: center; filter: drop-shadow(0 12px 30px rgba(255,45,45,0.4)); }
.mascot.floaty { animation: float 5s ease-in-out infinite; }
@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }

/* ── Disabled ───────────────────────────── */
.is-disabled { opacity: 0.45; pointer-events: none; filter: grayscale(0.3); }

/* ── Motifs ─────────────────────────────── */
.motif-rings { position: relative; overflow: hidden; }
.motif-rings::before, .motif-rings::after { content: ""; position: absolute; border: 1.5px solid rgba(255,45,45,0.5); border-radius: 50%; pointer-events: none; }
.motif-rings::before { width: 80px; height: 80px; right: -20px; top: -20px; }
.motif-rings::after { width: 140px; height: 140px; right: -50px; top: -50px; border-color: rgba(255,45,45,0.25); }

/* ── Loadbar ─────────────────────────────── */
.loadbar { height: 3px; background: rgba(255,255,255,0.08); border-radius: 999px; overflow: hidden; }
.loadbar > div { height: 100%; background: var(--electric-blue); border-radius: 999px; transition: width 0.6s ease; }